window.__PAGE_RUNTIME_PARTIALS__["partials/guia-06-mantener-equipos-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA \u0026middot; FPI\u003c/div\u003e\n      \u003ch2\u003eGu\u0026iacute;a 6 - Preparar el mantenimiento de equipos de c\u0026oacute;mputo\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinform\u0026aacute;ticos\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformaci\u0026oacute;n\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificaci\u0026oacute;n\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentaci\u0026oacute;n\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexi\u0026oacute;n Inicial\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualizaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#materiales\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128193;\u003c/span\u003e Materiales de apoyo\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eGu\u0026iacute;a asignada\u003c/div\u003e\n      \u003ca class=\"nav-guide current\" id=\"currentGuideNavLink\" href=\"grupo-10a-guia-06-mantener-equipos.html\" data-current-file=\"grupo-10a-guia-06-mantener-equipos.html\"\u003e\n        \u003cspan class=\"g-icon\"\u003e\u0026#128295;\u003c/span\u003e\n        \u003cspan class=\"g-info\"\u003e\n          \u003cspan class=\"g-num\"\u003eGu\u0026iacute;a 6\u003c/span\u003e\n          \u003cspan class=\"g-name\" id=\"currentGuideNavLabel\"\u003ePreparar el mantenimiento de equipos | 10A\u003c/span\u003e\n        \u003c/span\u003e\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\n        \u003cstrong\u003eGu\u0026iacute;a 6 - Preparar el mantenimiento de equipos de c\u0026oacute;mputo\u003c/strong\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003e80 horas\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eKennedy | Grado 10\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eGu\u0026iacute;a 6 | Fase: Planeaci\u0026oacute;n\u003c/div\u003e\n        \u003ch1\u003ePreparar el mantenimiento de los equipos de c\u0026oacute;mputo de acuerdo con procedimientos t\u0026eacute;cnicos y administrativos\u003c/h1\u003e\n        \u003cp\u003e\n          En esta gu\u0026iacute;a aprender\u0026aacute;s a diferenciar el mantenimiento preventivo del correctivo, a\n          interpretar manuales t\u0026eacute;cnicos de fabricante, a reconocer herramientas, materiales y elementos\n          de protecci\u0026oacute;n personal, y a preparar un plan de trabajo antes de intervenir un equipo real.\n        \u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Competencia: Mantener equipos de c\u0026oacute;mputo\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; 80 horas\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; C\u0026oacute;digo: 233108 \u0026middot; V1\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qu\u0026eacute; llevas y qu\u0026eacute; te falta?\u003c/h3\u003e\u003cp\u003eSe actualiza solo con tus entregas y respuestas guardadas\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eEsta tabla se marca sola: \u003cstrong\u003eEntregada\u003c/strong\u003e cuando subes la evidencia a Drive y\n            \u003cstrong\u003eGuardada\u003c/strong\u003e cuando guardas tus respuestas. Lo que siga en Pendiente es lo que te falta.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificaci\u0026oacute;n de la Gu\u0026iacute;a\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDatos del Programa de Formaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003eInformaci\u0026oacute;n oficial del programa y la competencia\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table ident-table\"\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eDenominaci\u0026oacute;n del Programa\u003c/td\u003e\u003ctd\u003eT\u0026eacute;cnico en Sistemas Teleinform\u0026aacute;ticos\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eC\u0026oacute;digo del Programa\u003c/td\u003e\u003ctd\u003e233108 \u0026middot; V1\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eAlfabetizaci\u0026oacute;n Digital, Asesor\u0026iacute;a T\u0026eacute;cnica y Ciberseguridad para la Mejora de Actividades Productivas Locales en la Zona de Influencia del CIAS.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003ePlaneaci\u0026oacute;n\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003ePlanificar procesos de intervenci\u0026oacute;n en alfabetizaci\u0026oacute;n digital, asesor\u0026iacute;a t\u0026eacute;cnica y ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e220501001 - Mantener equipos de c\u0026oacute;mputo seg\u0026uacute;n procedimiento t\u0026eacute;cnico.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003eRAP 01 - Preparar el mantenimiento de los equipos de c\u0026oacute;mputo de acuerdo con procedimientos t\u0026eacute;cnicos y administrativos.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDuraci\u0026oacute;n\u003c/td\u003e\u003ctd\u003e80 horas (60 horas de formaci\u0026oacute;n directa y 20 horas de trabajo independiente)\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eEmpieza por aquí:\u003c/strong\u003e conoce de qué trata la guía y qué vas a lograr. Léela completa antes de comenzar las actividades.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 ¿Cómo trabajar esta guía? Paso a paso\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eLee la teoría\u003c/strong\u003e de las secciones de contextualización antes de resolver las actividades.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eResuelve cada actividad\u003c/strong\u003e en orden. Escribe tus respuestas en los campos de la guía.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eGuarda tus respuestas\u003c/strong\u003e con el botón de cada actividad. Tu avance queda guardado en este navegador.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega las evidencias\u003c/strong\u003e que lo pidan con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e. Quedan en la carpeta de tu ficha.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eRevisa \"Tu control de avance\"\u003c/strong\u003e (arriba): te muestra qué llevas Entregado, Guardado y Pendiente.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e💡 Recuerda\u003c/div\u003e\n        \u003cp\u003eNo tienes que terminar todo de una vez: puedes salir y volver, tu trabajo se guarda solo. Si una actividad\n        ya fue entregada y necesitas corregirla, pídele a tu instructor que la habilite de nuevo.\u003c/p\u003e\u003c/div\u003e\n\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eBienvenida a la Gu\u0026iacute;a\u003c/h3\u003e\n              \u003cp\u003eConoce el contexto, el alcance y las metas de este recorrido formativo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003e\n            \u0026iexcl;Bienvenido, aprendiz! En el Magdalena Medio y el Occidente de Boyac\u0026aacute;, ferreter\u0026iacute;as,\n            miscel\u0026aacute;neas, droguer\u0026iacute;as y cooperativas agropecuarias dependen cada d\u0026iacute;a m\u0026aacute;s de sus\n            computadores para facturar, llevar inventarios y comunicarse con proveedores. Sin embargo, muy pocas\n            cuentan con un plan de mantenimiento: los equipos se intervienen solo cuando ya fallaron, casi\n            siempre en el peor momento.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            Un t\u0026eacute;cnico que sabe preparar el mantenimiento \u0026mdash; diagnosticar antes de actuar, consultar\n            los manuales correctos, alistar las herramientas adecuadas y documentar lo planeado \u0026mdash; evita\n            paradas de producci\u0026oacute;n, alarga la vida \u0026uacute;til de los equipos y protege la informaci\u0026oacute;n del\n            negocio. En esta gu\u0026iacute;a desarrollar\u0026aacute;s el RAP 01 de la competencia \u0026laquo;Mantener equipos de\n            c\u0026oacute;mputo seg\u0026uacute;n procedimiento t\u0026eacute;cnico\u0026raquo;: aprender\u0026aacute;s a diferenciar el mantenimiento\n            preventivo del correctivo, a interpretar manuales t\u0026eacute;cnicos de fabricante, a reconocer las\n            herramientas, materiales, elementos de limpieza y de protecci\u0026oacute;n personal necesarios, y a\n            preparar un plan de trabajo antes de intervenir un equipo real.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            El caso gu\u0026iacute;a de esta gu\u0026iacute;a es la \u003cstrong\u003eFerreter\u0026iacute;a y Miscel\u0026aacute;nea Puerto Real\u003c/strong\u003e, un\n            negocio familiar de Puerto Boyac\u0026aacute; (Magdalena Medio) que nunca ha recibido mantenimiento\n            programado en sus computadores. T\u0026uacute; ser\u0026aacute;s el t\u0026eacute;cnico que la ayude a cambiar esa situaci\u0026oacute;n.\n            Trabajar\u0026aacute;s en cuatro momentos: primero reflexionar\u0026aacute;s sobre el caso de Puerto Real; luego\n            estudiar\u0026aacute;s los conceptos clave de mantenimiento de equipos y practicar\u0026aacute;s una inspecci\u0026oacute;n\n            externa; despu\u0026eacute;s aplicar\u0026aacute;s ese conocimiento diagnosticando un equipo real del taller y\n            diligenciando su hoja de vida; y finalmente construir\u0026aacute;s, con ayuda de la herramienta HWMonitor,\n            un Plan de Mantenimiento Preventivo y Correctivo completo, que sustentar\u0026aacute;s ante el instructor.\n          \u003c/p\u003e\n          \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Lo que necesitas para esta gu\u0026iacute;a\u003c/div\u003e\n            \u003cp\u003e\n              Computador con suite ofim\u0026aacute;tica (LibreOffice o Microsoft Office), acceso a internet,\n              destornilladores de precisi\u0026oacute;n, pulsera antiest\u0026aacute;tica, soplador de aire comprimido y el\n              formato de hoja de vida de equipos suministrado por el instructor. Algunas actividades son de\n              trabajo directo con el instructor y otras de trabajo independiente. Lea siempre las instrucciones\n              completas antes de empezar y guarde cada evidencia con nombre descriptivo.\n              \u003cstrong\u003eSin evidencia, no hay evaluaci\u0026oacute;n.\u003c/strong\u003e\n            \u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.1 REFLEXIÓN INICIAL ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 \u0026middot; Actividades de Reflexi\u0026oacute;n Inicial\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de reflexión inicial:\u003c/strong\u003e activa lo que ya sabes sobre el tema. Aquí no se evalúa el acierto, sino tu participación: responde con confianza, no hay respuestas malas.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eActivar lo que usted ya sabe sobre mantenimiento de equipos y reconocer el costo de no\n        planificarlo, antes de entrar a los conceptos t\u0026eacute;cnicos. Metodolog\u0026iacute;a: aprendizaje basado en\n        problemas (ABP), con la t\u0026eacute;cnica activa de lluvia de ideas en equipo. Todo el tiempo de reflexi\u0026oacute;n\n        es trabajo directo con el instructor.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-reflexion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128172;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Reflexi\u0026oacute;n Inicial\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 1 hora directa\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.1.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003e\u0026laquo;Detectives del mantenimiento\u0026raquo;: el caso de la Ferreter\u0026iacute;a Puerto Real\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e en grupos de 3 o 4, analizar por lluvia de ideas los s\u0026iacute;ntomas del caso Puerto Real. Duraci\u0026oacute;n: 30 minutos directas.\u003c/p\u003e\n\n              \u003carticle class=\"story-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso \u0026mdash; Ferreter\u0026iacute;a y Miscel\u0026aacute;nea Puerto Real, Puerto Boyac\u0026aacute; (Magdalena Medio)\u003c/h3\u003e\n                \u003cp\u003eEste negocio familiar tiene 4 computadores: facturaci\u0026oacute;n, bodega, contabilidad y un punto\n                de atenci\u0026oacute;n. Nunca han recibido mantenimiento programado. Esta semana, el computador de\n                facturaci\u0026oacute;n se calienta demasiado, su ventilador suena fuerte y en ocasiones no reconoce la\n                memoria USB del lector de c\u0026oacute;digo de barras.\u003c/p\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px;\"\u003e\n                \u003ch3\u003eLluvia de ideas en grupo (3 o 4 personas)\u003c/h3\u003e\n                \u003cp class=\"intro-text\" style=\"margin-top:0;font-size:.9rem\"\u003e\n                  No es necesario entregar un producto escrito por el grupo: registra aqu\u0026iacute; tus propias\n                  respuestas como participante de la discusi\u0026oacute;n.\n                \u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. \u0026iquest;Qu\u0026eacute; s\u0026iacute;ntomas del computador de facturaci\u0026oacute;n llaman su atenci\u0026oacute;n? Enumere al menos 3.\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_311_sintomas\" data-track placeholder=\"Ej.: se calienta demasiado, el ventilador suena fuerte, a veces no reconoce el USB del lector de codigo de barras.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. \u0026iquest;Qu\u0026eacute; posibles causas t\u0026eacute;cnicas podr\u0026iacute;an explicar cada s\u0026iacute;ntoma?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_311_causas\" data-track placeholder=\"Relaciona cada sintoma con una posible causa (polvo acumulado, ventilador danado, puerto USB con falla, etc.).\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. \u0026iquest;Qu\u0026eacute; herramientas o equipos de protecci\u0026oacute;n creen que necesitar\u0026aacute;n antes de abrir el computador?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_311_herramientas\" data-track placeholder=\"Ej.: destornillador de precision, pulsera antiestatica, soplador de aire comprimido.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. \u0026iquest;Qu\u0026eacute; precauciones tomar\u0026iacute;an para no perder informaci\u0026oacute;n ni da\u0026ntilde;ar m\u0026aacute;s el equipo?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_311_precauciones\" data-track placeholder=\"Ej.: hacer copia de seguridad de la facturacion antes de intervenir, desconectar el equipo de la corriente.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. \u0026iquest;Alguna vez han visto un computador con s\u0026iacute;ntomas parecidos en su casa, colegio o negocio familiar? \u0026iquest;Qu\u0026eacute; pas\u0026oacute;?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_311_experiencia\" data-track placeholder=\"Describe brevemente una experiencia propia o cercana con sintomas similares.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"caso311DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarCaso311\" class=\"btn-save-response\" onclick=\"actStd_save_caso311()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_caso311()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusCaso311\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.1.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eSocializaci\u0026oacute;n en plenaria\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e compartir el hallazgo m\u0026aacute;s preocupante de cada grupo y cerrar con una reflexi\u0026oacute;n sobre mantenimiento preventivo vs. correctivo. Duraci\u0026oacute;n: 30 minutos directas.\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eCada grupo comparte en m\u0026aacute;ximo 2 minutos su s\u0026iacute;ntoma m\u0026aacute;s preocupante y la causa que consideran m\u0026aacute;s probable.\u003c/li\u003e\n                  \u003cli\u003eEl instructor registra en el tablero los s\u0026iacute;ntomas y agrupa las causas por tipo: mec\u0026aacute;nicas, el\u0026eacute;ctricas, de software o de falta de limpieza.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px;\"\u003e\n                \u003ch3\u003eBit\u0026aacute;cora de cierre\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. S\u0026iacute;ntoma m\u0026aacute;s preocupante que compartiste con el grupo general y la causa m\u0026aacute;s probable\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_312_sintoma_grupo\" data-track placeholder=\"Resume lo que tu grupo compartio en la plenaria.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Idea final: \u0026iquest;qu\u0026eacute; relaci\u0026oacute;n encuentra entre \u0026laquo;no hacer mantenimiento preventivo\u0026raquo; y \u0026laquo;terminar haciendo mantenimiento correctivo urgente\u0026raquo;?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_312_reflexion\" data-track placeholder=\"Escribe tu conclusion personal sobre preventivo vs. correctivo, con base en lo discutido en plenaria.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"plenaria312DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlenaria312\" class=\"btn-save-response\" onclick=\"actStd_save_plenaria312()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plenaria312()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlenaria312\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.2 CONTEXTUALIZACIÓN ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 \u0026middot; Contextualizaci\u0026oacute;n e Identificaci\u0026oacute;n de Conocimientos\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de contextualización:\u003c/strong\u003e aquí están los conceptos y la teoría que necesitas. Estúdialos con calma — son la base para resolver bien las actividades que siguen.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eConstruir la base conceptual sobre tipos de mantenimiento, manuales t\u0026eacute;cnicos,\n        materiales/herramientas y elementos de protecci\u0026oacute;n, y aplicarla en una primera inspecci\u0026oacute;n\n        externa. Metodolog\u0026iacute;a: aprendizaje colaborativo con estudio por bloques tem\u0026aacute;ticos + demostraci\u0026oacute;n guiada.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-contexto\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128269;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Contextualizaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 10 horas (7 directas + 3 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.2.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEstudio de contenidos de mantenimiento de equipos (Bloques A y B)\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n diagn\u0026oacute;stica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e estudiar en equipo de 3 los 7 temas de los Bloques A y B, y consolidar una tabla resumen exportada a PDF: \u003ccode\u003eBloqueAB_RAP01_[TuNombre]_v1.0.pdf\u003c/code\u003e. Duraci\u0026oacute;n: 7 horas directas + 3 horas independientes previas.\u003c/p\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (3 horas, ANTES de la sesi\u0026oacute;n)\u003c/div\u003e\n                \u003cp\u003eEstudie los temas de los Bloques A y B usando los m\u0026oacute;dulos de IT Essentials de Cisco\n                Networking Academy (netacad.com) y los manuales t\u0026eacute;cnicos que le indique el instructor.\n                Tome apuntes en su bit\u0026aacute;cora. Llegue a clase con los conceptos b\u0026aacute;sicos de mantenimiento\n                preventivo, correctivo y elementos de protecci\u0026oacute;n revisados.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:16px\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:30%\"\u003eTema (Bloque A \u0026mdash; Tipos y diagn\u0026oacute;stico de mantenimiento)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eMantenimiento preventivo\u003c/td\u003e\u003ctd\u003eConcepto, periodicidad, ventajas y ejemplos aplicados a equipos de c\u0026oacute;mputo (limpieza interna, verificaci\u0026oacute;n de temperaturas, actualizaci\u0026oacute;n de software).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eMantenimiento correctivo\u003c/td\u003e\u003ctd\u003eConcepto, diferencias con el preventivo, cu\u0026aacute;ndo se aplica y riesgos de solo hacer mantenimiento correctivo.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eDiagn\u0026oacute;stico de equipos\u003c/td\u003e\u003ctd\u003eS\u0026iacute;ntomas comunes de falla f\u0026iacute;sica y l\u0026oacute;gica, y su relaci\u0026oacute;n con posibles causas (sobrecalentamiento, ruido, fallas de reconocimiento de dispositivos).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eManuales t\u0026eacute;cnicos\u003c/td\u003e\u003ctd\u003eQu\u0026eacute; contienen (especificaciones, procedimientos de desarme, garant\u0026iacute;a) y c\u0026oacute;mo se consultan en el sitio del fabricante.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:12px\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:30%\"\u003eTema (Bloque B \u0026mdash; Materiales, herramientas y protecci\u0026oacute;n personal)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eHerramientas de mantenimiento\u003c/td\u003e\u003ctd\u003eDestornilladores de precisi\u0026oacute;n, pulsera antiest\u0026aacute;tica, soplador de aire comprimido, brochas: funci\u0026oacute;n y uso correcto de cada una.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eElementos de limpieza y productos qu\u0026iacute;micos\u003c/td\u003e\u003ctd\u003eAlcohol isopropil\u0026iacute;co, aire comprimido, limpia contactos: caracter\u0026iacute;sticas, usos y precauciones de manejo.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eElementos de protecci\u0026oacute;n personal (EPP)\u003c/td\u003e\u003ctd\u003ePulsera antiest\u0026aacute;tica y su funci\u0026oacute;n para evitar descargas electrost\u0026aacute;ticas (ESD) que da\u0026ntilde;en componentes.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones para la sesi\u0026oacute;n directa\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eForme un equipo de 3 personas. Repartan los 7 temas (4 del Bloque A + 3 del Bloque B): m\u0026iacute;nimo 2 temas por integrante.\u003c/li\u003e\n                  \u003cli\u003eDurante la primera hora, cada integrante explica sus temas al equipo (5 minutos por tema) mientras los dem\u0026aacute;s completan sus apuntes.\u003c/li\u003e\n                  \u003cli\u003eEn LibreOffice Calc o Google Sheets, construyan una tabla de 3 columnas: \u0026laquo;Tema\u0026raquo;, \u0026laquo;\u0026iquest;Para qu\u0026eacute; sirve?\u0026raquo;, \u0026laquo;Ejemplo aplicado en la Ferreter\u0026iacute;a Puerto Real\u0026raquo;. Completen una fila por tema.\u003c/li\u003e\n                  \u003cli\u003eEl instructor realiza una plenaria de cierre donde cada equipo comparte su fila m\u0026aacute;s importante.\u003c/li\u003e\n                  \u003cli\u003eExporten la tabla a PDF con el nombre \u003cstrong\u003eBloqueAB_RAP01_[TuNombre]_v1.0.pdf\u003c/strong\u003e y comp\u0026aacute;rtanla por el medio indicado por el instructor.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eRegistro guiado del aprendiz\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Reparto del equipo: temas y responsable de cada uno\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_321_reparto\" data-track placeholder=\"Ej.: Ana: mantenimiento preventivo, correctivo. Luis: diagnostico de equipos, manuales tecnicos. Yo: herramientas, limpieza, EPP.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Temas que estudiaste t\u0026uacute; (de los 7 distribuidos en tu equipo)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_321_temas\" data-track placeholder=\"Lista los temas que te tocaron y la fuente principal que revisaste (IT Essentials, manual tecnico).\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Tema de tu fila en la tabla resumen\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g6mant_321_tema_fila\" data-track placeholder=\"Ej.: Elementos de proteccion personal (EPP).\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. \u0026iquest;Para qu\u0026eacute; sirve?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_321_paraque\" data-track placeholder=\"Explica el concepto con tus palabras, sin copiar y pegar definiciones.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Ejemplo aplicado en la Ferreter\u0026iacute;a Puerto Real\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_321_ejemplo\" data-track placeholder=\"Ej.: antes de abrir el computador de facturacion, el tecnico usa pulsera antiestatica para no danar la placa madre.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"bloqueAB321DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloqueAB321\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueAB321()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_bloqueAB321()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloqueAB321\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-bloqueAB321\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.2.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEjercicio de inspecci\u0026oacute;n externa de equipos de c\u0026oacute;mputo\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n diagn\u0026oacute;stica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e inspeccionar externamente un equipo real del taller y diligenciar el formato de inspecci\u0026oacute;n suministrado por el instructor. Duraci\u0026oacute;n: 3 horas directas (+ 8 horas independientes despu\u0026eacute;s, de consulta sobre diagn\u0026oacute;stico de fallas).\u003c/p\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones \u0026mdash; sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eEn equipo de m\u0026aacute;ximo 4 integrantes, reciban del instructor un equipo de c\u0026oacute;mputo del taller (sin abrirlo todav\u0026iacute;a).\u003c/li\u003e\n                  \u003cli\u003eRealicen una inspecci\u0026oacute;n puramente externa: estado f\u0026iacute;sico de la carcasa, puertos, cables, ventilaci\u0026oacute;n, ruidos al encender, temperatura al tacto en la carcasa despu\u0026eacute;s de 10 minutos de uso.\u003c/li\u003e\n                  \u003cli\u003eRegistren sus hallazgos en el \u003ca href=\"assets/materiales/guia6mant/Formato_Inspeccion_Externa_Equipos.pdf\" target=\"_blank\" rel=\"noopener\"\u003eformato de inspecci\u0026oacute;n externa\u003c/a\u003e suministrado por el instructor, indicando para cada \u0026iacute;tem si es normal o si requiere atenci\u0026oacute;n.\u003c/li\u003e\n                  \u003cli\u003eRedacten un informe corto (m\u0026aacute;ximo 1 p\u0026aacute;gina) con sus conclusiones: \u0026iquest;el equipo parece requerir mantenimiento preventivo, correctivo, o ambos? Justifiquen con base en lo observado.\u003c/li\u003e\n                  \u003cli\u003eAdicionalmente, con base en el mismo equipo inspeccionado, diligencien la tabla de identificaci\u0026oacute;n de dispositivos de entrada, salida y almacenamiento.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (8 horas, ANTES de la sesi\u0026oacute;n)\u003c/div\u003e\n                \u003cp\u003eConsulte los recursos sobre diagn\u0026oacute;stico de fallas de hardware y software recomendados por\n                el instructor (m\u0026oacute;dulos IT Essentials de Cisco Networking Academy y manuales t\u0026eacute;cnicos de\n                fabricantes). Elabore en su bit\u0026aacute;cora una tabla personal de \u0026laquo;s\u0026iacute;ntoma \u0026rarr; posible causa\n                \u0026rarr; tipo de mantenimiento\u0026raquo; con m\u0026iacute;nimo 8 casos.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInforme de inspecci\u0026oacute;n (registro del aprendiz)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Hallazgos de la inspecci\u0026oacute;n externa (estado f\u0026iacute;sico, puertos, cables, ventilaci\u0026oacute;n, ruidos, temperatura)\u003c/span\u003e\n                  \u003ctextarea rows=\"6\" data-store=\"g6mant_322_hallazgos\" data-track placeholder=\"Describe lo observado en cada aspecto de la inspeccion externa.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Conclusiones (m\u0026aacute;ximo 1 p\u0026aacute;gina): \u0026iquest;el equipo requiere mantenimiento preventivo, correctivo o ambos? Justifica.\u003c/span\u003e\n                  \u003ctextarea rows=\"6\" data-store=\"g6mant_322_conclusion\" data-track placeholder=\"Redacta tu conclusion tecnica justificada con base en los hallazgos.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Dispositivo(s) de entrada identificados en el equipo: definici\u0026oacute;n breve y ubicaci\u0026oacute;n f\u0026iacute;sica\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_322_disp_entrada\" data-track placeholder=\"Ej.: teclado y mouse USB, conectados en los puertos traseros.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Dispositivo(s) de salida identificados en el equipo: definici\u0026oacute;n breve y ubicaci\u0026oacute;n f\u0026iacute;sica\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_322_disp_salida\" data-track placeholder=\"Ej.: monitor conectado por HDMI, parlantes en el conector de audio.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Dispositivo(s) de almacenamiento identificados en el equipo: definici\u0026oacute;n breve y ubicaci\u0026oacute;n f\u0026iacute;sica\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_322_disp_almacenamiento\" data-track placeholder=\"Ej.: disco duro interno de 1TB, identificado al abrir la carcasa lateral.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"inspeccion322DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarInspeccion322\" class=\"btn-save-response\" onclick=\"actStd_save_inspeccion322()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_inspeccion322()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusInspeccion322\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-inspeccion322\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.3 APROPIACIÓN ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 \u0026middot; Actividades de Apropiaci\u0026oacute;n del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de apropiación:\u003c/strong\u003e pones en práctica lo aprendido. La mayoría de las evidencias que debes entregar salen de esta fase.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eProfundizar en el diagn\u0026oacute;stico t\u0026eacute;cnico de equipos y en el diligenciamiento de la\n        documentaci\u0026oacute;n de soporte (hoja de vida del equipo), aplicando criterio t\u0026eacute;cnico frente a casos\n        reales. Metodolog\u0026iacute;a: estudio de caso + aprendizaje basado en problemas (ABP), con trabajo guiado\n        por el instructor.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-apropiacion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128218;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Apropiaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 32 horas (24 directas + 8 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.3.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eConsulta y an\u0026aacute;lisis guiado de fallas comunes\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n t\u0026eacute;cnica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e estudiar el Bloque C de diagn\u0026oacute;stico avanzado y analizar dos nuevos reportes del caso Puerto Real. Duraci\u0026oacute;n: 12 horas directas + 8 horas independientes previas.\u003c/p\u003e\n\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:16px\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:30%\"\u003eTema (Bloque C \u0026mdash; Diagn\u0026oacute;stico avanzado)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eFallas f\u0026iacute;sicas frecuentes\u003c/td\u003e\u003ctd\u003eAcumulaci\u0026oacute;n de polvo, ventiladores obstruidos, conexiones sueltas, deterioro de pasta t\u0026eacute;rmica, oxidaci\u0026oacute;n de contactos.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eFallas l\u0026oacute;gicas frecuentes\u003c/td\u003e\u003ctd\u003eSoftware desactualizado, fragmentaci\u0026oacute;n, malware, arranque lento, procesos que consumen recursos en exceso.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eRelaci\u0026oacute;n entre s\u0026iacute;ntoma y causa\u003c/td\u003e\u003ctd\u003eC\u0026oacute;mo asociar un s\u0026iacute;ntoma reportado por el usuario (ej. \u0026laquo;el equipo se calienta y hace ruido\u0026raquo;) con posibles causas f\u0026iacute;sicas o l\u0026oacute;gicas.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003ePriorizaci\u0026oacute;n de intervenci\u0026oacute;n\u003c/td\u003e\u003ctd\u003eCriterios para decidir qu\u0026eacute; se atiende primero: riesgo para el equipo, impacto en la operaci\u0026oacute;n del negocio, complejidad de la soluci\u0026oacute;n.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"story-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso \u0026mdash; Ferreter\u0026iacute;a Puerto Real: nuevos hallazgos\u003c/h3\u003e\n                \u003cp\u003eDespu\u0026eacute;s de la inspecci\u0026oacute;n externa de la Actividad 3.2.2, el propietario entrega dos\n                reportes adicionales: (1) el equipo de facturaci\u0026oacute;n se reinicia solo cuando corre el\n                software contable durante m\u0026aacute;s de una hora; (2) el equipo de la bodega no reconoce la\n                impresora de c\u0026oacute;digo de barras aunque el cable USB est\u0026aacute; conectado. El propietario\n                pregunta si esto se soluciona con mantenimiento preventivo o si ya es correctivo.\u003c/p\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones para la sesi\u0026oacute;n directa\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eEn equipo de m\u0026aacute;ximo 4 integrantes, analicen los dos reportes usando su tabla de s\u0026iacute;ntoma-causa como referencia.\u003c/li\u003e\n                  \u003cli\u003ePara cada reporte, determinen: tipo de mantenimiento requerido (preventivo, correctivo o ambos), posibles causas ordenadas de m\u0026aacute;s a menos probable, y nivel de urgencia (alta, media, baja).\u003c/li\u003e\n                  \u003cli\u003eRedacten una recomendaci\u0026oacute;n t\u0026eacute;cnica dirigida al propietario, en lenguaje claro y sin tecnicismos innecesarios, explicando qu\u0026eacute; se va a hacer y por qu\u0026eacute;.\u003c/li\u003e\n                  \u003cli\u003eSocialicen su an\u0026aacute;lisis en plenaria; el instructor retroalimenta la pertinencia t\u0026eacute;cnica de cada diagn\u0026oacute;stico.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eAn\u0026aacute;lisis t\u0026eacute;cnico (registro del aprendiz)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Estudio del Bloque C: notas sobre fallas f\u0026iacute;sicas, l\u0026oacute;gicas, relaci\u0026oacute;n s\u0026iacute;ntoma-causa y priorizaci\u0026oacute;n\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g6mant_331_bloqueC\" data-track placeholder=\"Resume lo que estudiaste del Bloque C antes de la sesion directa.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Reporte 1 (facturaci\u0026oacute;n se reinicia sola): tipo de mantenimiento, causas probables y urgencia\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_331_reporte1\" data-track placeholder=\"Analiza el reporte 1: preventivo/correctivo, causas ordenadas y nivel de urgencia.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Reporte 2 (impresora de bodega no reconocida): tipo de mantenimiento, causas probables y urgencia\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_331_reporte2\" data-track placeholder=\"Analiza el reporte 2: preventivo/correctivo, causas ordenadas y nivel de urgencia.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Recomendaci\u0026oacute;n t\u0026eacute;cnica redactada para el propietario (lenguaje claro, sin tecnicismos)\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g6mant_331_recomendacion\" data-track placeholder=\"Redacta la recomendacion final dirigida al propietario de la ferreteria.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"analisis331DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarAnalisis331\" class=\"btn-save-response\" onclick=\"actStd_save_analisis331()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_analisis331()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusAnalisis331\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-analisis331\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.3.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eDiagn\u0026oacute;stico t\u0026eacute;cnico y diligenciamiento de hoja de vida del equipo\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n t\u0026eacute;cnica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e diagnosticar t\u0026eacute;cnicamente un equipo distinto al de la Actividad 3.2.2 y diligenciar su hoja de vida completa. Duraci\u0026oacute;n: 12 horas directas.\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eInstrucciones \u0026mdash; sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eReciban del instructor un equipo de c\u0026oacute;mputo distinto al usado en la Actividad 3.2.2, junto con el formato de hoja de vida de equipos.\u003c/li\u003e\n                  \u003cli\u003eRealicen un diagn\u0026oacute;stico t\u0026eacute;cnico completo: inspecci\u0026oacute;n externa, encendido y verificaci\u0026oacute;n de funcionamiento b\u0026aacute;sico (sistema operativo, perif\u0026eacute;ricos, temperatura, ruido).\u003c/li\u003e\n                  \u003cli\u003eDiligencien la hoja de vida del equipo con todos los datos requeridos: identificaci\u0026oacute;n del equipo, especificaciones t\u0026eacute;cnicas, historial de intervenci\u0026oacute;n (si aplica), diagn\u0026oacute;stico actual y recomendaci\u0026oacute;n de mantenimiento.\u003c/li\u003e\n                  \u003cli\u003eEntreguen al instructor la hoja de vida diligenciada para revisi\u0026oacute;n y retroalimentaci\u0026oacute;n individual.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128193; Formatos oficiales de hoja de vida (usa el que te indique el instructor)\u003c/div\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u003ca href=\"assets/materiales/guia6mant/GA-F-05-HV-de-Equipos-de-Computo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eGA-F-05 \u0026mdash; Hoja de Vida de Equipos de C\u0026oacute;mputo (PDF)\u003c/a\u003e\u003c/li\u003e\n                  \u003cli\u003e\u003ca href=\"assets/materiales/guia6mant/f-gr-02-hoja-de-vida-equipos-tecnologicos.pdf\" target=\"_blank\" rel=\"noopener\"\u003eF-GR-02 \u0026mdash; Hoja de Vida de Equipos Tecnol\u0026oacute;gicos (PDF)\u003c/a\u003e\u003c/li\u003e\n                  \u003cli\u003e\u003ca href=\"assets/materiales/guia6mant/GT-FO-01-FORMATO-HOJAS-DE-VIDA-EQUIPOS-V03.xlsx\" target=\"_blank\" rel=\"noopener\"\u003eGT-FO-01 \u0026mdash; Formato Hojas de Vida de Equipos, V03 (Excel)\u003c/a\u003e\u003c/li\u003e\n                  \u003cli\u003e\u003ca href=\"assets/materiales/guia6mant/f-ga-146-ficha-tecnica-equipos-de-computo.xlsx\" target=\"_blank\" rel=\"noopener\"\u003eF-GA-146 \u0026mdash; Ficha T\u0026eacute;cnica de Equipos de C\u0026oacute;mputo (Excel)\u003c/a\u003e\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eDiagn\u0026oacute;stico y hoja de vida (registro del aprendiz)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Diagn\u0026oacute;stico t\u0026eacute;cnico completo: inspecci\u0026oacute;n externa, sistema operativo, perif\u0026eacute;ricos, temperatura y ruido\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g6mant_332_diagnostico\" data-track placeholder=\"Describe el resultado del diagnostico tecnico completo del equipo asignado.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Hoja de vida \u0026mdash; identificaci\u0026oacute;n del equipo (marca, modelo, serial, ubicaci\u0026oacute;n)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_332_hv_identificacion\" data-track placeholder=\"Datos de identificacion registrados en la hoja de vida.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Hoja de vida \u0026mdash; especificaciones t\u0026eacute;cnicas y historial de intervenci\u0026oacute;n (si aplica)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_332_hv_especificaciones\" data-track placeholder=\"Procesador, RAM, disco, sistema operativo y cualquier intervencion previa conocida.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Recomendaci\u0026oacute;n de mantenimiento registrada en la hoja de vida\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_332_hv_recomendacion\" data-track placeholder=\"Recomendacion tecnica final que dejaste registrada en la hoja de vida.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"diagnostico332DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarDiagnostico332\" class=\"btn-save-response\" onclick=\"actStd_save_diagnostico332()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_diagnostico332()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusDiagnostico332\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-diagnostico332\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.4 TRANSFERENCIA ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 \u0026middot; Actividades de Transferencia del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de transferencia:\u003c/strong\u003e aplicas todo lo aprendido a un caso real o a una actividad integradora. Suele ser la evidencia más importante de la guía.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eAplicar de manera integral lo aprendido, elaborando un plan de mantenimiento preventivo real\n        para el equipo de c\u0026oacute;mputo de un negocio, con monitoreo t\u0026eacute;cnico de par\u0026aacute;metros y sustentaci\u0026oacute;n\n        ante el instructor. Metodolog\u0026iacute;a: aprendizaje basado en proyectos, con producto final evaluable.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-transferencia\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128640;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Transferencia\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 37 horas (28 directas + 9 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.4.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eLaboratorio de monitoreo t\u0026eacute;cnico con HWMonitor\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n t\u0026eacute;cnica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e monitorear temperatura y velocidad de ventiladores con HWMonitor durante 3 d\u0026iacute;as y consolidar una tabla comparativa en equipo. Duraci\u0026oacute;n: 12 horas directas + 9 horas independientes previas.\u003c/p\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (9 horas)\u003c/div\u003e\n                \u003cp\u003eInstale en un equipo de c\u0026oacute;mputo (propio, del hogar o del taller, seg\u0026uacute;n indique el\n                instructor) el software \u003ca href=\"https://www.cpuid.com\" target=\"_blank\" rel=\"noopener\"\u003eHWMonitor\u003c/a\u003e\n                u otra herramienta de monitoreo equivalente autorizada por el instructor. Explore sus funciones:\n                temperatura de CPU, velocidad de ventiladores, voltajes. Durante 3 d\u0026iacute;as, registre en una\n                tabla las lecturas en tres momentos: equipo reci\u0026eacute;n encendido, despu\u0026eacute;s de 30 minutos de uso\n                normal, y despu\u0026eacute;s de 30 minutos de uso exigente (varios programas abiertos). Consulta el\n                \u003ca href=\"assets/materiales/guia6mant/HWMonitor_Manual_Usuario.pdf\" target=\"_blank\" rel=\"noopener\"\u003emanual de usuario de HWMonitor\u003c/a\u003e\n                y el \u003ca href=\"assets/materiales/guia6mant/Anexo_Reporte_Ejemplo_HWMonitor.pdf\" target=\"_blank\" rel=\"noopener\"\u003ereporte de ejemplo\u003c/a\u003e como gu\u0026iacute;a.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones \u0026mdash; sesi\u0026oacute;n directa\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eEn equipo de trabajo, comparen sus registros individuales y discutan qu\u0026eacute; valores se consideran normales y cu\u0026aacute;les indican posible sobrecalentamiento o falla de ventilaci\u0026oacute;n, apoy\u0026aacute;ndose en las especificaciones t\u0026eacute;cnicas del fabricante consultadas en la Actividad 3.2.1.\u003c/li\u003e\n                  \u003cli\u003eElaboren una tabla comparativa consolidada del equipo, con conclusiones sobre el estado t\u0026eacute;rmico de los equipos monitoreados y recomendaciones de mantenimiento preventivo.\u003c/li\u003e\n                  \u003cli\u003eExporten sus registros a hoja de c\u0026aacute;lculo (XLSX) y luego a PDF.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eRegistro de monitoreo (registro del aprendiz)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Registros individuales de los 3 d\u0026iacute;as (temperatura y velocidad de ventiladores en los 3 momentos)\u003c/span\u003e\n                  \u003ctextarea rows=\"6\" data-store=\"g6mant_341_registros\" data-track placeholder=\"Resume tus lecturas de los 3 dias: encendido, 30 min uso normal, 30 min uso exigente.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Tabla comparativa consolidada del equipo (resultado del trabajo en equipo)\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g6mant_341_comparativa\" data-track placeholder=\"Resume la tabla comparativa consolidada por el equipo.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Conclusiones sobre el estado t\u0026eacute;rmico y recomendaciones de mantenimiento preventivo\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g6mant_341_conclusion\" data-track placeholder=\"Conclusiones tecnicas y recomendaciones de mantenimiento preventivo.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"hwmonitor341DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarHwmonitor341\" class=\"btn-save-response\" onclick=\"actStd_save_hwmonitor341()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_hwmonitor341()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusHwmonitor341\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-hwmonitor341\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.4.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003ePlan de Mantenimiento Preventivo y sustentaci\u0026oacute;n\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e elaborar el Plan de Mantenimiento Preventivo para los 4 equipos de la Ferreter\u0026iacute;a Puerto Real y sustentarlo ante el instructor. Duraci\u0026oacute;n: 16 horas directas.\u003c/p\u003e\n\n              \u003carticle class=\"story-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026#127970; Caso \u0026mdash; Ferreter\u0026iacute;a Puerto Real: cierre del proceso\u003c/h3\u003e\n                \u003cp\u003eCon base en todo lo trabajado (inspecci\u0026oacute;n externa, diagn\u0026oacute;stico t\u0026eacute;cnico, hojas de\n                vida y monitoreo t\u0026eacute;rmico), el propietario de la Ferreter\u0026iacute;a Puerto Real les solicita\n                formalmente un Plan de Mantenimiento Preventivo para sus 4 equipos de c\u0026oacute;mputo, que le\n                permita anticiparse a fallas y planificar el gasto en mantenimiento durante el a\u0026ntilde;o.\u003c/p\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128193; Ejemplos de referencia (planes de mantenimiento reales)\u003c/div\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u003ca href=\"assets/materiales/guia6mant/Plan_de_Mantenimiento_Ejemplo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eEjemplo de Plan de Mantenimiento (PDF)\u003c/a\u003e\u003c/li\u003e\n                  \u003cli\u003e\u003ca href=\"assets/materiales/guia6mant/Programa_Mantenimiento_Ejemplo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eEjemplo de Programa de Mantenimiento V1R3 (PDF)\u003c/a\u003e\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones \u0026mdash; sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eEn equipo de m\u0026aacute;ximo 4 integrantes, elaboren el Plan de Mantenimiento Preventivo para los 4 equipos del caso, incluyendo como m\u0026iacute;nimo: cronograma anual de intervenciones, actividades a realizar en cada visita, materiales y herramientas necesarias, elementos de protecci\u0026oacute;n personal requeridos, y responsable de cada actividad.\u003c/li\u003e\n                  \u003cli\u003eAnexen al plan las hojas de vida diligenciadas en la Actividad 3.3.2 como soporte del estado inicial de los equipos.\u003c/li\u003e\n                  \u003cli\u003ePreparen una sustentaci\u0026oacute;n oral de m\u0026aacute;ximo 10 minutos por equipo, explicando su plan como si se lo presentaran directamente al propietario del negocio.\u003c/li\u003e\n                  \u003cli\u003eSustenten ante el instructor y sus compa\u0026ntilde;eros. El instructor eval\u0026uacute;a dominio t\u0026eacute;cnico, claridad de la propuesta y pertinencia de las recomendaciones frente al caso.\u003c/li\u003e\n                  \u003cli\u003eEntreguen el Plan de Mantenimiento Preventivo en formato digital final, incluyendo las hojas de vida como anexos.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003ePlan de Mantenimiento Preventivo (borrador previo a la redacci\u0026oacute;n)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Cronograma anual de intervenciones para los 4 equipos\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_342_cronograma\" data-track placeholder=\"Frecuencia y fechas propuestas de mantenimiento para cada uno de los 4 equipos.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Actividades a realizar en cada visita de mantenimiento\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g6mant_342_actividades\" data-track placeholder=\"Ej.: limpieza interna, verificacion de temperaturas, actualizacion de software.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Materiales y herramientas necesarias\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_342_materiales\" data-track placeholder=\"Ej.: destornilladores de precision, aire comprimido, alcohol isopropilico.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Elementos de protecci\u0026oacute;n personal (EPP) requeridos\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g6mant_342_epp\" data-track placeholder=\"Ej.: pulsera antiestatica.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Responsable de cada actividad del plan\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g6mant_342_responsables\" data-track placeholder=\"Indica quien del equipo queda a cargo de cada actividad del plan.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"planMantenimiento342DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlanMantenimiento342\" class=\"btn-save-response\" onclick=\"actStd_save_planMantenimiento342()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_planMantenimiento342()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlanMantenimiento342\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-planMantenimiento342\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ MATERIALES DE APOYO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"materiales\" class=\"section-title\"\u003eMateriales de Apoyo\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eConsulta aquí\u003c/strong\u003e los formatos oficiales, ejemplos y documentos de referencia que necesitas para las actividades de esta guía.\u003c/p\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e0f2f1\"\u003e\u0026#128193;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eFormatos, ejemplos y documentos t\u0026eacute;cnicos\u003c/h3\u003e\n              \u003cp\u003eDescarga los materiales suministrados por el instructor\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\n                  \u003cth\u003eMaterial\u003c/th\u003e\n                  \u003cth\u003eActividad\u003c/th\u003e\n                  \u003cth\u003eEnlace\u003c/th\u003e\n                \u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eFormato de Inspecci\u0026oacute;n Externa de Equipos\u003c/td\u003e\u003ctd\u003e3.2.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Formato_Inspeccion_Externa_Equipos.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eGA-F-05 \u0026mdash; Hoja de Vida de Equipos de C\u0026oacute;mputo\u003c/td\u003e\u003ctd\u003e3.3.1 \u0026middot; 3.3.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/GA-F-05-HV-de-Equipos-de-Computo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eF-GR-02 \u0026mdash; Hoja de Vida de Equipos Tecnol\u0026oacute;gicos\u003c/td\u003e\u003ctd\u003e3.3.1 \u0026middot; 3.3.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/f-gr-02-hoja-de-vida-equipos-tecnologicos.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eGT-FO-01 \u0026mdash; Formato Hojas de Vida de Equipos (V03, Excel)\u003c/td\u003e\u003ctd\u003e3.3.1 \u0026middot; 3.3.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/GT-FO-01-FORMATO-HOJAS-DE-VIDA-EQUIPOS-V03.xlsx\" target=\"_blank\" rel=\"noopener\"\u003eAbrir Excel\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eF-GA-146 \u0026mdash; Ficha T\u0026eacute;cnica de Equipos de C\u0026oacute;mputo (Excel)\u003c/td\u003e\u003ctd\u003e3.3.1 \u0026middot; 3.3.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/f-ga-146-ficha-tecnica-equipos-de-computo.xlsx\" target=\"_blank\" rel=\"noopener\"\u003eAbrir Excel\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad \u0026laquo;El Detective\u0026raquo; (caso ampliado)\u003c/td\u003e\u003ctd\u003e3.1.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/1_Actividad_El_Detective.docx\" target=\"_blank\" rel=\"noopener\"\u003eAbrir Word\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eManual de usuario de HWMonitor\u003c/td\u003e\u003ctd\u003e3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/HWMonitor_Manual_Usuario.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eReporte de ejemplo con HWMonitor\u003c/td\u003e\u003ctd\u003e3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Anexo_Reporte_Ejemplo_HWMonitor.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eEjemplo de Plan de Mantenimiento\u003c/td\u003e\u003ctd\u003e3.4.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Plan_de_Mantenimiento_Ejemplo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eEjemplo de Programa de Mantenimiento (V1R3)\u003c/td\u003e\u003ctd\u003e3.4.2\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Programa_Mantenimiento_Ejemplo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eArquitectura de PC (referencia t\u0026eacute;cnica)\u003c/td\u003e\u003ctd\u003e3.2.1 \u0026middot; 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Arquitectura_PC.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eArquitectura de Laptops (referencia t\u0026eacute;cnica)\u003c/td\u003e\u003ctd\u003e3.2.1 \u0026middot; 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Arquitectura_Laptops.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eConexi\u0026oacute;n M.2 y SATA (referencia t\u0026eacute;cnica)\u003c/td\u003e\u003ctd\u003e3.2.1 \u0026middot; 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Conexion_M2_y_SATA.docx\" target=\"_blank\" rel=\"noopener\"\u003eAbrir Word\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eManual de mantenimiento del computador\u003c/td\u003e\u003ctd\u003e3.2.1 \u0026middot; 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Manual_Mantenimiento_del_Computador.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u0026laquo;Mantenimiento preventivo y correctivo para PCs\u0026raquo; (Guti\u0026eacute;rrez, Pe\u0026ntilde;afiel, Villarreal)\u003c/td\u003e\u003ctd\u003e3.2.1 \u0026middot; 3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Comunidad_Emagister_Mantenimiento_Preventivo.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCap\u0026iacute;tulo 2 \u0026mdash; Conocimiento del Hardware (componentes internos, reglas de seguridad y hoja de especificaciones)\u003c/td\u003e\u003ctd\u003e3.2.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Modulo_2_Referencia_Adicional.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128295; Software de monitoreo (instalaci\u0026oacute;n externa, Actividad 3.4.1)\u003c/div\u003e\n            \u003cp\u003eHWMonitor se instala directamente desde el sitio oficial del fabricante:\n            \u003ca href=\"https://www.cpuid.com\" target=\"_blank\" rel=\"noopener\"\u003ecpuid.com\u003c/a\u003e. Si no tienes acceso a\n            internet en el equipo donde vas a monitorear, ped\u0026iacute;le al instructor el instalador en USB.\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ EVIDENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003ePlanteamiento de Evidencias para la Evaluaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eResumen de lo que debes entregar:\u003c/strong\u003e usa esta sección como lista de chequeo final. Revisa que no te falte ninguna evidencia y cómo se evalúa cada una.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--entrega\"\u003e\u003cdiv class=\"gnote__label\"\u003e📦 Antes de entregar, revisa\u003c/div\u003e\n        \u003cul\u003e\n          \u003cli\u003eRespondiste todas las actividades que se piden como evidencia.\u003c/li\u003e\n          \u003cli\u003eTus archivos tienen tu nombre y número de ficha.\u003c/li\u003e\n          \u003cli\u003eSubiste cada evidencia con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e y la ves marcada como \u003cstrong\u003eEntregada\u003c/strong\u003e en tu control de avance.\u003c/li\u003e\n        \u003c/ul\u003e\u003c/div\u003e\n\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128202;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eTabla de Evidencias del Proceso Formativo\u003c/h3\u003e\n              \u003cp\u003e3 evidencias: conocimiento, desempe\u0026ntilde;o y producto\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\n                  \u003cth\u003eActividad de Aprendizaje\u003c/th\u003e\n                  \u003cth\u003eEvidencias\u003c/th\u003e\n                  \u003cth\u003eCriterios\u003c/th\u003e\n                  \u003cth\u003eInstrumento\u003c/th\u003e\n                \u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.1 + 3.2.1 \u0026mdash; Reflexi\u0026oacute;n inicial y estudio de contenidos de mantenimiento\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eCONOCIMIENTO:\u003c/strong\u003e cuestionario sobre tipos de mantenimiento (preventivo y correctivo), herramientas de diagn\u0026oacute;stico y normas de seguridad el\u0026eacute;ctrica.\u003c/td\u003e\n                  \u003ctd\u003eDetermina el tipo de mantenimiento de los equipos de c\u0026oacute;mputo de acuerdo con el procedimiento t\u0026eacute;cnico establecido. Interpreta los manuales t\u0026eacute;cnicos del fabricante de acuerdo con la labor a realizar.\u003c/td\u003e\n                  \u003ctd\u003eIE-01 \u0026mdash; Cuestionario de conocimiento\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.2.2 + 3.3.1 + 3.3.2 \u0026mdash; Inspecci\u0026oacute;n externa, an\u0026aacute;lisis de fallas y diagn\u0026oacute;stico t\u0026eacute;cnico con hoja de vida\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eDESEMPE\u0026Ntilde;O:\u003c/strong\u003e inspecci\u0026oacute;n y diagn\u0026oacute;stico del estado f\u0026iacute;sico y funcional de equipos de c\u0026oacute;mputo reales del taller, aplicando normas de seguridad.\u003c/td\u003e\n                  \u003ctd\u003eOrganiza el puesto de trabajo con los equipos, herramientas, materiales, elementos de protecci\u0026oacute;n, productos qu\u0026iacute;micos y manejo de residuos de acuerdo con normatividad vigente.\u003c/td\u003e\n                  \u003ctd\u003eIE-02 \u0026mdash; Lista de chequeo de desempe\u0026ntilde;o\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.4.1 + 3.4.2 \u0026mdash; Laboratorio de monitoreo con HWMonitor y Plan de Mantenimiento Preventivo\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003ePRODUCTO:\u003c/strong\u003e hoja de vida del equipo diligenciada y plan de mantenimiento propuesto para los equipos inspeccionados.\u003c/td\u003e\n                  \u003ctd\u003eElabora plan de trabajo seg\u0026uacute;n requerimientos y condiciones administrativas.\u003c/td\u003e\n                  \u003ctd\u003eIE-03 \u0026mdash; Lista de chequeo de producto\u003c/td\u003e\n                \u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ GLOSARIO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de T\u0026eacute;rminos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#fff3e0\"\u003e\u0026#128214;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eConceptos clave de mantenimiento de equipos\u003c/h3\u003e\n              \u003cp\u003e8 t\u0026eacute;rminos t\u0026eacute;cnicos\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary-list\"\u003e\n            \u003cdt\u003eMantenimiento preventivo\u003c/dt\u003e\u003cdd\u003eConjunto de actividades programadas y realizadas de forma peri\u0026oacute;dica sobre un equipo de c\u0026oacute;mputo con el fin de evitar fallas antes de que ocurran, prolongando su vida \u0026uacute;til.\u003c/dd\u003e\n            \u003cdt\u003eMantenimiento correctivo\u003c/dt\u003e\u003cdd\u003eIntervenci\u0026oacute;n que se realiza sobre un equipo de c\u0026oacute;mputo despu\u0026eacute;s de que se ha presentado una falla, con el prop\u0026oacute;sito de restablecer su funcionamiento normal.\u003c/dd\u003e\n            \u003cdt\u003eCRU (Customer Replaceable Unit)\u003c/dt\u003e\u003cdd\u003eComponente o unidad de un equipo de c\u0026oacute;mputo que puede ser reemplazada directamente por el usuario o t\u0026eacute;cnico sin necesidad de intervenci\u0026oacute;n especializada del fabricante.\u003c/dd\u003e\n            \u003cdt\u003eEPP (Elementos de Protecci\u0026oacute;n Personal)\u003c/dt\u003e\u003cdd\u003eEquipos o dispositivos que protegen al t\u0026eacute;cnico de riesgos durante las labores de mantenimiento, como la pulsera antiest\u0026aacute;tica.\u003c/dd\u003e\n            \u003cdt\u003eESD (Electrostatic Discharge)\u003c/dt\u003e\u003cdd\u003eDescarga electrost\u0026aacute;tica que puede da\u0026ntilde;ar componentes electr\u0026oacute;nicos sensibles si no se toman las precauciones adecuadas (uso de pulsera antiest\u0026aacute;tica, superficies de trabajo aterrizadas).\u003c/dd\u003e\n            \u003cdt\u003eRAEE\u003c/dt\u003e\u003cdd\u003eResiduos de Aparatos El\u0026eacute;ctricos y Electr\u0026oacute;nicos: desechos generados por equipos electr\u0026oacute;nicos en desuso, que requieren disposici\u0026oacute;n especial seg\u0026uacute;n normatividad ambiental vigente.\u003c/dd\u003e\n            \u003cdt\u003eHoja de vida del equipo\u003c/dt\u003e\u003cdd\u003eDocumento t\u0026eacute;cnico que registra la informaci\u0026oacute;n completa de un equipo de c\u0026oacute;mputo: identificaci\u0026oacute;n, especificaciones, historial de intervenciones y estado actual.\u003c/dd\u003e\n            \u003cdt\u003eManual t\u0026eacute;cnico\u003c/dt\u003e\u003cdd\u003eDocumento suministrado por el fabricante que contiene las especificaciones, procedimientos de uso, mantenimiento y garant\u0026iacute;a de un equipo o componente.\u003c/dd\u003e\n          \u003c/dl\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ REFERENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes Bibliogr\u0026aacute;ficos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#ede7f6\"\u003e\u0026#128279;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eFuentes oficiales y normativas\u003c/h3\u003e\n              \u003cp\u003e6 referencias t\u0026eacute;cnicas y normativas para consulta\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003col class=\"references-list\" style=\"padding-left:1.4rem;line-height:1.8\"\u003e\n            \u003cli\u003eCisco Networking Academy. \u003cem\u003eIT Essentials: PC Hardware and Software (v8.0)\u003c/em\u003e. \u003ca href=\"https://www.netacad.com\" target=\"_blank\" rel=\"noopener\"\u003enetacad.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje \u0026mdash; SENA. \u003cem\u003eDise\u0026ntilde;o Curricular T\u0026eacute;cnico en Sistemas Teleinform\u0026aacute;ticos\u003c/em\u003e, versi\u0026oacute;n 233108. SENA, Regional Boyac\u0026aacute;.\u003c/li\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje \u0026mdash; SENA. \u003cem\u003eBiblioteca Virtual SENA\u003c/em\u003e. \u003ca href=\"https://biblioteca.sena.edu.co\" target=\"_blank\" rel=\"noopener\"\u003ebiblioteca.sena.edu.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMinisterio de Ambiente y Desarrollo Sostenible. \u003cem\u003eResoluci\u0026oacute;n 1297 de 2010\u003c/em\u003e y \u003cem\u003eDecreto 284 de 2018\u003c/em\u003e sobre gesti\u0026oacute;n de Residuos de Aparatos El\u0026eacute;ctricos y Electr\u0026oacute;nicos (RAEE). Colombia. \u003ca href=\"assets/materiales/guia6mant/resolucion-1297-de-2010.pdf\" target=\"_blank\" rel=\"noopener\"\u003eResoluci\u0026oacute;n 1297/2010 (PDF)\u003c/a\u003e \u0026middot; \u003ca href=\"assets/materiales/guia6mant/Decreto_284_de_2018.pdf\" target=\"_blank\" rel=\"noopener\"\u003eDecreto 284/2018 (PDF)\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMueller, S. (2021). \u003cem\u003eUpgrading and Repairing PCs\u003c/em\u003e (23rd ed.). Que Publishing.\u003c/li\u003e\n            \u003cli\u003eCPUID. \u003cem\u003eHWMonitor\u003c/em\u003e \u0026mdash; Manual de usuario del software de monitoreo de hardware. \u003ca href=\"https://www.cpuid.com\" target=\"_blank\" rel=\"noopener\"\u003ecpuid.com\u003c/a\u003e\u003c/li\u003e\n          \u003c/ol\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
